fn main() -> i64 {
    match read_file("./data/tokens.txt") {
        Ok(text) => {
            let parts = str_split(str_replace(text, "\n", ","), ",")
            let counts = dict_new()
            for i in 0..len(parts) {
                let t = str_trim(parts[i])
                if str_len(t) > 0 {
                    dict_inc(counts, t)
                }
            }
            let keys = dict_keys(counts)
            let n = len(keys)
            if n == 0 {
                eprintln("no tokens found")
                return 1
            }
            let first = 0
            for i in 1..n {
                if dict_get_or(counts, keys[i], 0) > dict_get_or(counts, keys[first], 0) {
                    first = i
                }
            }
            let second = n
            for i in 0..n {
                if i != first {
                    if second == n {
                        second = i
                    } else if dict_get_or(counts, keys[i], 0) > dict_get_or(counts, keys[second], 0) {
                        second = i
                    }
                }
            }
            if second == n {
                eprintln("fewer than two distinct tokens")
                return 1
            }
            match write_file("./out/answer.txt", keys[second] + "\n") {
                Ok(_) => 0
                Err(e) => {
                    eprintln("cannot write: {e}")
                    1
                }
            }
        }
        Err(e) => {
            eprintln("cannot read: {e}")
            2
        }
    }
}
